@Test
public void testLog() {
    PrintStream output = Mockito.mock(PrintStream.class);
    System.setOut(output);
    PrintStream err = Mockito.mock(PrintStream.class);
    System.setErr(err);
    EasyLogger logger = new EasyLogger(EasyLoggerTest.class) {

